import React from "react";
import "./EmotionalCard.css"; // Import CSS
import Cat1 from "../assets/Cat1.png"; // Import the cat image
import Paw from "../public/Paw.png"; // Import the paw image

function EmotionalCard() {
  return (
    <div className="emotional-card">
      <img src={Paw} alt="Paw Icon" className="paw-icon" />
      <h3 className="card-title">Emotional relationship</h3>
      <p className="card-text">
        The emotional bond between cats and humans is deeply rooted in felines'
        unconditional love and companionship.
      </p>
      <img src={Cat1} alt="Cat Icon" className="cat-icon" />
    </div>
  );
}

export default EmotionalCard;
